CREATE TABLE music_artist (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, resource_id UUID NOT NULL, kind VARCHAR(32) NOT NULL, sort_name VARCHAR(512), disambiguation VARCHAR(512), version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(resource_id) REFERENCES resource(id), UNIQUE(owner_id,resource_id));
CREATE TABLE music_album (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, resource_id UUID NOT NULL, kind VARCHAR(32) NOT NULL, original_release_date TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(resource_id) REFERENCES resource(id), UNIQUE(owner_id,resource_id));
CREATE TABLE music_edition (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, album_id UUID NOT NULL, edition_name VARCHAR(512), release_date TIMESTAMPTZ, country VARCHAR(64), label VARCHAR(256), catalog_number VARCHAR(128), medium_type VARCHAR(64), version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(album_id) REFERENCES music_album(id));
CREATE TABLE music_disc (id UUID PRIMARY KEY DEFAULT uuid_v7(), edition_id UUID NOT NULL, disc_number INTEGER NOT NULL, title VARCHAR(512), medium_format VARCHAR(64), position INTEGER NOT NULL, CHECK(disc_number>0), FOREIGN KEY(edition_id) REFERENCES music_edition(id), UNIQUE(edition_id,disc_number));
CREATE TABLE music_track (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, resource_id UUID NOT NULL, title VARCHAR(512) NOT NULL, duration_millis BIGINT, isrc VARCHAR(64), explicit BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0, CHECK(duration_millis IS NULL OR duration_millis>=0), FOREIGN KEY(resource_id) REFERENCES resource(id), UNIQUE(owner_id,resource_id));
CREATE TABLE music_track_membership (id UUID PRIMARY KEY DEFAULT uuid_v7(), edition_id UUID NOT NULL, disc_id UUID NOT NULL, track_id UUID NOT NULL, track_number INTEGER NOT NULL, sort_order INTEGER NOT NULL, title_override VARCHAR(512), duration_millis BIGINT, hidden BOOLEAN NOT NULL DEFAULT FALSE, CHECK(track_number>0), FOREIGN KEY(edition_id) REFERENCES music_edition(id), FOREIGN KEY(disc_id) REFERENCES music_disc(id), FOREIGN KEY(track_id) REFERENCES music_track(id), UNIQUE(edition_id,disc_id,track_number));
CREATE TABLE music_audio_source (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, track_id UUID NOT NULL, attachment_id UUID NOT NULL, codec VARCHAR(64), container VARCHAR(64), duration_millis BIGINT, sample_rate INTEGER, bit_depth INTEGER, channels INTEGER, bitrate INTEGER, lossless BOOLEAN NOT NULL DEFAULT FALSE, availability VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE', preference_weight INTEGER NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, CHECK(duration_millis IS NULL OR duration_millis>=0), FOREIGN KEY(track_id) REFERENCES music_track(id), FOREIGN KEY(attachment_id) REFERENCES attachment(id), UNIQUE(track_id,attachment_id));
CREATE TABLE music_playlist (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, name VARCHAR(512) NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE music_playlist_entry (id UUID PRIMARY KEY DEFAULT uuid_v7(), playlist_id UUID NOT NULL, track_id UUID NOT NULL, position INTEGER NOT NULL, added_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, CHECK(position>=0), FOREIGN KEY(playlist_id) REFERENCES music_playlist(id) ON DELETE CASCADE, FOREIGN KEY(track_id) REFERENCES music_track(id));
CREATE INDEX idx_music_playlist_entries ON music_playlist_entry(playlist_id,position);
